class GymMember{private static int counter=2000;private final String membershipNumber;private int feesPaid;GymMember(int fee){membershipNumber="GYM-"+(++counter);}void payFee(int amount){feesPaid+=amount;}void payFee(int amount,String mode){payFee(amount);}int getFeesPaid(){return feesPaid;}static boolean isValidReferralCode(String c){return c!=null&&c.length()==4&&c.charAt(0)=='G'&&Character.isDigit(c.charAt(1))&&Character.isDigit(c.charAt(2))&&Character.isUpperCase(c.charAt(3));}static int getMembersEnrolled(){return counter-2000;}}
class GroupClassMember extends GymMember{GroupClassMember(int fee,String c){super(fee);}}
public class Main{static String processWeeklyCheckIn(GymMember[] ms){int p=0,n=0,g=0,i=0;for(GymMember m:ms){if(m==null){n++;continue;}p++;if(m instanceof GroupClassMember)g++;else i++;}return p+" processed | "+n+" null skipped | "+g+" group | "+i+" individual";}public static void main(String[]a){}}